# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the title bar's Copilot meter: how much of the seat's premium quota is used this
#          period, shaped for the page ('premium 4%', the credits on hover, the reset day).
#          The Copilot counterpart of spend.py's month meter (dollars, a Gateway model).
# Usage: AVAILABLE says whether the meter is on the page (a github-copilot model);
#        load() -> CopilotMeter on app open and on the meter's refresh button (1 GitHub
#        request).
# ---------------------------------------------------------------------------
from __future__ import annotations

import datetime as dt
from dataclasses import dataclass, field
from typing import Any

import httpx2
from ds.ai.model import seat_usage_tracked
from ds.data.raw.copilot import CopilotRefusedError, CopilotUsage, Quota, copilot_usage, usage_from_headers

from ui.spend import DANGER_AT, WARN_AT

# True while the model is a GitHub Copilot one (ds.ai.model): the meter is on the page (ui.py)
AVAILABLE: bool = seat_usage_tracked()


@dataclass
class CopilotMeter:
    """The meter as the page shows it. `ok` False: the read failed and `problem` says why
    (the page then keeps the figures it had).
    """

    ok: bool = True
    problem: str = ""
    percent: str = "--%"
    """Shown in the bar: '4%', '<1%', 'unlimited', 'unknown'."""
    detail: str = "-- / --"
    """Shown in its place on hover: '22 / 7,000 credits'."""
    resets: str = ""
    """'resets 12/01', '' when GitHub gave no day."""
    meter: str = "0%"
    level: str = ""
    title: str = "Reading the Copilot seat's usage…"
    as_of: str = ""
    """When it was read, local time, eg '11/20 10:33'."""
    plan: str = ""
    unit: str = "requests"
    """As GitHub gave them at the last full read: an answer's headers don't carry them."""
    usage: dict[str, Any] = field(default_factory=dict)
    """The CopilotUsage it was built from ({} before a read), for from_answer to add to."""


def _number(value: float) -> str:
    """'7,000', and '35.5' for a part credit (GitHub counts them in tenths)."""
    return f"{value:,.1f}".removesuffix(".0")


def _percent(value: float) -> str:
    return "<1%" if 0 < value < 1 else f"{value:.0f}%"


def _others(usage: CopilotUsage) -> str:
    """The quotas that aren't in the bar, for the tooltip, eg 'chat: unlimited'."""
    named = (("chat", usage.chat), ("completions", usage.completions))
    return " · ".join(
        f"{name}: {'unlimited' if quota.unlimited else _percent(quota.percent_used)}" for name, quota in named if quota
    )


def _title(usage: CopilotUsage, premium: Quota | None, *, rounded: bool = False) -> str:
    parts = []
    if premium and not premium.unlimited:
        left = premium.limit - premium.used
        parts.append(
            f"{_number(left)} premium {usage.unit} remaining"
            if left >= 0
            else f"{_number(-left)} premium {usage.unit} over"
        )
    if usage.resets:
        parts.append(f"resets {usage.resets:%Y-%m-%d}")
    if usage.plan:
        parts.append(f"Copilot plan: {usage.plan}")
    if others := _others(usage):
        parts.append(others)
    source = (
        "The count is rounded from the last AI answer's percent: the refresh button reads the exact one."
        if rounded
        else "GitHub's count when read, plus what this app's AI answers cost since (use elsewhere: refresh)."
    )
    return " · ".join(parts) + f". {source}"


def build(usage: CopilotUsage, now: dt.datetime, *, rounded: bool = False) -> CopilotMeter:
    """The meter from a read. `now`: when it was read, in the zone to show it in. rounded:
    the count was worked out from a percent (from_answer), so it is shown as 'about 42'.
    """
    premium = usage.premium
    out = CopilotMeter(
        resets=f"resets {usage.resets:%m/%d}" if usage.resets else "",
        title=_title(usage, premium, rounded=rounded),
        as_of=f"{now:%m/%d %H:%M}",
        plan=usage.plan,
        unit=usage.unit,
        usage=usage.model_dump(mode="json"),
    )
    if premium is None:
        out.percent, out.detail = "unknown", "GitHub gave no premium quota"
    elif premium.unlimited:
        out.percent, out.detail = "unlimited", f"{_number(premium.used)} {usage.unit} used"
    else:
        share = premium.percent_used / 100
        out.percent = _percent(premium.percent_used)
        used = f"about {premium.used:,.0f}" if rounded else _number(premium.used)
        out.detail = f"{used} / {_number(premium.limit)} {usage.unit}"
        out.meter = f"{min(100.0, premium.percent_used):.1f}%"
        out.level = "danger" if share >= DANGER_AT else "warn" if share >= WARN_AT else "ok"
    return out


STEP = 0.001  # an answer's headers give the share left to a thousandth of the limit


def from_answer(headers: dict[str, str], spent: float, shown: dict[str, Any], now: dt.datetime) -> CopilotMeter | None:
    """The meter after the app's own AI answers, from what those answers said themselves
    (ds.ai.model leaves it on the call): no request is sent. None: nothing to change.

    Args:
        headers: the last answer's quota headers (the share left, to STEP of the limit).
        spent: what the answers cost in credits, 0 when they didn't say.
        shown: the meter on the page; its `usage` is the last one read or worked out.
        now: when, in the zone to show it in.

    The count stays exact while the answers say what they cost: it is added to the count
    shown. Else, or when the headers are further off than their own rounding (the seat was
    used elsewhere, eg in VS Code), the headers' rounded count is shown as 'about 42'.
    """
    seen = usage_from_headers(headers)
    if seen is None or seen.premium is None:
        return None
    known = CopilotUsage(**shown["usage"]) if shown.get("usage") else None
    if known is None or known.premium is None or known.premium.unlimited or not known.premium.limit:
        seen.plan, seen.unit = shown.get("plan", ""), shown.get("unit") or "requests"
        return build(seen, now, rounded=True)
    premium = known.premium
    premium.used += spent
    premium.percent_used = 100 * premium.used / premium.limit
    known.resets = seen.resets or known.resets
    if abs(seen.premium.used - premium.used) > STEP * premium.limit:
        seen.plan, seen.unit = known.plan, known.unit
        return build(seen, now, rounded=True)
    if not spent:
        return None
    return build(known, now)


def load() -> CopilotMeter:
    """Read the seat's usage and shape it: 1 GitHub request. A refusal or a failed request
    comes back as ok=False with what happened, never raised.
    """
    try:
        usage = copilot_usage()
    except CopilotRefusedError as error:
        return CopilotMeter(ok=False, problem=str(error))
    except httpx2.HTTPError as error:
        return CopilotMeter(ok=False, problem=f"GitHub couldn't be read ({type(error).__name__})")
    return build(usage, dt.datetime.now().astimezone())
